  "implementation": "def solve(case):
    attempts = case["attempts"]
    max_attempts = case["max_attempts"]
    if any(a["success"] for a in attempts):
        return {"decision": "finalize", "memory_append": None, "next_attempt": len(attempts)}
    else:
        if len(attempts) < max_attempts:
            last = attempts[-1]
            return {"decision": "retry", "memory_append": {"reflection": last["reflection"], "signature": last["failure_signature"]}, "next_attempt": len(attempts)}
        else:
            return {"decision": "finalize", "memory_append": None, "next_attempt": len(attempts)}"
